INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(92881, 'ruRU', 'Ночнорождённый. Я не доверяю тебе и твоему народу.', '', 24330),
(92882, 'ruRU', 'Я понимаю, добрый дракон. Мой народ заслужил твоё недоверие. Позволь мне всё исправить.', '', 24330),
(92883, 'ruRU', 'Прекрасно! Тогда в Зарчинар. Повидать всех друзей, семью и близких.', '', 24330),
(92884, 'ruRU', '...чтобы убить их, разумеется, за то, что они навредили твоему дракону.', '', 24330),
(92885, 'ruRU', 'Та ещё компания манозависимых, ха-ха! Но не я. У меня железная дисциплина.', '', 24330),
(92886, 'ruRU', 'Оо! Мана-кристалл. Секундочку.', '', 24330),
(92887, 'ruRU', 'Так... зачем ты здесь, в Азсуне, друг? Просто в гостях, или...?', '', 24330),
(92888, 'ruRU', 'Он вообще когда-нибудь замолкает?', '', 24330),
(92889, 'ruRU', 'Прошу прощения, добрый дракон. Ах, смотри! Мы на месте.', '', 24330),
(92890, 'ruRU', 'Этот голод пожирает сам мой разум. Уходит каждая капля сил просто... просто...', '', 24330),
(92905, 'ruRU', '|TInterface\\Icons\\inv_blacksmithdye_black.blp:20|t %s сбросил |cFFFF0000|Hspell:180147|h[Боеприпасы Скверны]|h|r.', '', 24330),
(92936, 'ruRU', 'Черпание силы', '', 24330),
(92937, 'ruRU', 'Они делали со мной... вещи...', '', 24330),
(92938, 'ruRU', 'Я не сдался.', '', 24330),
(92939, 'ruRU', 'Демоны обещали нам невообразимую силу.', '', 24330),
(92940, 'ruRU', 'Стражница пыталась убедить нас предать своих. Я слышал крики.', '', 24330),
(92941, 'ruRU', 'Циана Ночной Клинок предала нас. Она присоединилась к Легиону.', '', 24330),
(92942, 'ruRU', 'Ночной Клинок отправилась на юго-запад со стражницей по имени Кордана Скверпесня.', '', 24330),
(92943, 'ruRU', 'Всё будет поглощено моим пламенем!', '', 24330),
(92944, 'ruRU', '|TInterface\\Icons\\ability_fixated_state_purple:20|t%s |cFFFF0404|Hspell:180148|h[Фиксируется]|h|r на вас!', '', 24330),
(92950, 'ruRU', 'Отведи меня на Железный фронт.', '', 24330),
(92969, 'ruRU', 'Эти новые орки Скверны сражаются отчаянно. Это не скоро закончится...', '', 24330),
(92970, 'ruRU', 'Мы начали осаду в тот момент, как ты захватил лодки. Мы сражались осторожно, пока крупный отряд Железной Орды не ушёл — вероятно, против тебя. Вот тогда мы и нанесли настоящий удар!$b$bТвой Газлоу соорудил ужасающее устройство, чтобы разрушить ворота, и мы ринулись внутрь... но столкнулись с новым противником... орками Скверны. Им удалось остановить наше наступление и удержать нас здесь. Надеюсь, на востоке тебе повезло больше.', '', 24330),
(92971, 'ruRU', ';p;', '', 24330),
(92972, 'ruRU', 'Какая обстановка?', '', 24330),
(92973, 'ruRU', 'Приём пищи', '', 24330),
(92974, 'ruRU', 'Каз сказал, что я могу помочь! Это место такое крутое!$b$bЯ могу рассказать тебе про Зет\'Гол на северо-западе, Храм Ша\'наар на юге и Зорамскую трясину на юго-востоке.', '', 24330),
(92975, 'ruRU', 'Эм, ладно... так что у тебя для меня, разведчик Каттер?', '', 24330),
(92976, 'ruRU', 'Ага! Так вот, эти ребята из Кровавой Пустоши почти так же опасны, как Смеющийся Череп, но они слишком много времени проводят, глядя в небо. У них куча ловушек, и охотятся они как ящеры в джунглях. Глубже в их городе они творят странные вещи с кровью и магией.$b$bДумаю, если провести магнарона через центр этой деревни, пользы будет много!', '', 24330),
(92977, 'ruRU', 'Командир, берегись! Саргерай здесь!', '', 24330),
(92978, 'ruRU', 'Саргерай? Что там происходит?', '', 24330),
(92979, 'ruRU', 'Они уже какое-то время как перебили местных жителей. Я не смог подобраться слишком близко, но они оскверняют живую природу энергией Скверны и призывают демонов.$b$bЭту павшую деревню нужно сровнять с землёй, командир.', '', 24330),
(92981, 'ruRU', 'Эй, командирша. Аракоа тут, в Дозоре Актара. Ещё я проверил тот здоровенный туннель на юго-востоке.', '', 24330);
